#!/usr/bin/env python3
"""Generate the raw assembly source map used by the modular browser player."""

from __future__ import annotations

import json
import pathlib
import sys

from source_catalog import source_text

ROOT = pathlib.Path(__file__).resolve().parent.parent
OUTPUT = pathlib.Path(sys.argv[1]).resolve() if len(sys.argv) > 1 else ROOT / "web" / "sources.js"

sources = source_text()
OUTPUT.write_text(
    "// Generated by tools/build_web_sources.py; do not edit.\n"
    + "window.EMBEDDED_ASM="
    + json.dumps(sources, ensure_ascii=False, separators=(",", ":"))
    + ";\n",
    encoding="utf-8",
)
print(f"{OUTPUT} ({len(sources)} assembly sources)")
